<script setup>
import {ref} from 'vue';import {router} from '@inertiajs/vue3';
const props=defineProps({scope:Object,admin:Boolean}),busy=ref(false),error=ref('');
function review(topic=null){busy.value=true;error.value='';router.post('/progress/review',{...props.scope.filters,...(topic?{review_subject:topic.subject,review_topic:topic.topic_key}:{})},{onError:errors=>error.value=Object.values(errors).join(' '),onFinish:()=>busy.value=false})}
</script>
<template>
<div class="stat-grid progress-summary" aria-label="Progress in selected filters"><div class="stat"><strong>{{scope.first_total?Math.round(scope.first_correct/scope.first_total*100)+'%':'—'}}</strong><span>First-answer accuracy</span><small>{{scope.first_correct}} correct / {{scope.first_total}} first answers</small></div><div class="stat"><strong>{{scope.covered}} / {{scope.available}}</strong><span>Questions covered</span><small>Distinct questions answered</small></div><div class="stat"><strong>{{scope.need_review}}</strong><span>Need review</span><small>Latest answer incorrect</small></div></div>
<details class="metric-help"><summary>How these numbers are counted</summary><p>All three cards use the selected subjects, topics, dates, difficulty, and study tool. Dates use Asia/Manila. The denominator for coverage is the matching active question bank today.</p><p>First-answer accuracy uses each question’s first-ever recorded answer, when that answer falls in the selected period. Coverage counts each answered question once within the period. Need review uses the latest answer across all dates and tools, then checks that answer against these filters. A later correct answer removes an earlier mistake.</p><p>Unreleased assigned-exam answers are excluded. Imported results with unknown history count toward all-time coverage; they do not enter first-answer accuracy. Recall ratings remain separate from correctness.</p></details>
<section class="panel"><div class="review-heading"><h2>Review next</h2><button v-if="!admin&&scope.need_review" :disabled="busy" @click="review()">{{busy?'Starting…':'Review up to 20'}}</button></div><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="!scope.need_review">No questions need review in these filters.</p><div v-else class="review-topics"><div v-for="topic in scope.topics" :key="topic.subject+topic.topic_key" class="review-topic"><div><strong>{{topic.topic}}</strong><p class="field-help">{{topic.subject}} · {{topic.count}} {{topic.count===1?'question':'questions'}}</p></div><button v-if="!admin" :disabled="busy" :aria-label="'Review '+topic.subject+' · '+topic.topic" @click="review(topic)">Review topic</button></div></div><p v-if="scope.need_review" class="field-help">Each review starts a practice session with up to 20 questions from the displayed filters.</p></section>
</template>
